const { nodeResolve } = require("@rollup/plugin-node-resolve");
const { wasm } = require("./build/wasm-plugin.cjs");
const commonJs = require("@rollup/plugin-commonjs");
const nodePolyfills = require("rollup-plugin-polyfill-node");
const typescript = require("@rollup/plugin-typescript");
const json = require("@rollup/plugin-json");
const replace = require("@rollup/plugin-replace");
const path = require("path");
const copy = require("rollup-plugin-copy");

const pathPolyfill = (useNodePath = false) => ({
  name: "path-polyfill",
  resolveId(importee, importer) {
    if (importee === "path" || importee === "node:path") {
      if (
        useNodePath &&
        importer &&
        importer.endsWith("src/path-polyfill.js")
      ) {
        return { id: importee, external: true };
      }
      return require.resolve("./src/path-polyfill.js");
      // Hack to allow importing modules not in package.json#exports
    } else if (
      importee.startsWith("@cyclonedx/cyclonedx-library/") &&
      importee.endsWith(".js")
    ) {
      const pkgRoot = path.dirname(
        require.resolve("@cyclonedx/cyclonedx-library/package.json"),
      );
      const fileToLoad = importee.replace("@cyclonedx/cyclonedx-library/", "");
      return path.join(pkgRoot, fileToLoad);
    }
  },
});

const rollupAlias = {
  name: "rollup-browser-alias",
  resolveId(importee) {
    if (importee === "rollup") {
      return require.resolve("@rollup/browser");
    }
  },
};

const nullModules = (nullModuleList = []) => ({
  name: "null-modules",
  resolveId(importee) {
    if (nullModuleList.includes(importee)) {
      return importee;
    }
  },
  load(id) {
    if (nullModuleList.includes(id)) {
      return "export default {};";
    }
  },
});

const config = {
  plugins: [
    commonJs(),
    nodeResolve(),
    typescript(),
    json(),
    replace({
      preventAssignment: true,
      "process.versions.node": JSON.stringify(process.versions.node),
    }),
    {
      name: "fs-scurry",
      resolveId(importee) {
        if (
          importee === "fs" ||
          importee === "node:fs" ||
          importee === "node:fs/promises" ||
          importee === "node:url"
        ) {
          return require.resolve("./src/fs-scurry.js");
        }
      },
    },
    {
      name: "minipass",
      resolveId(importee) {
        if (importee === "minipass") {
          return require.resolve("./src/minipass.js");
        }
      },
    },
    wasm({ targetEnv: "auto", fileName: "[name].[hash][extname]" }),
  ],
};

/**
 * @type {import('rollup').RollupOptions}
 */
module.exports = [
  /**
   * Browser-based build config
   */
  {
    input: "src/index.ts",
    output: {
      format: "esm",
      sourcemap: true,
      file: "dist/browser/index.js",
      inlineDynamicImports: true,
    },
    plugins: [
      rollupAlias,
      nullModules([
        "@swc/core",
        "rollup-plugin-dev",
        "rollup-plugin-livereload",
      ]),
      pathPolyfill(),
      ...config.plugins,
      nodePolyfills(),
      copy({
        targets: [
          {
            src: "src/node-resolve/index.d.ts",
            dest: "dist/browser/node-resolve",
          }, // Copy all .d.ts files from src to dist
          {
            src: require.resolve("@rollup/browser/dist/bindings_wasm_bg.wasm"),
            dest: "dist/browser",
          },
        ],
      }),
    ],
  },
  /**
   * Node.js-based build config
   */
  {
    input: "src/index.ts",
    external: [
      "sass",
      "fs",
      "rollup",
      "@swc/core",
      "rollup-plugin-dev",
      "rollup-plugin-livereload",
    ],
    output: {
      format: "cjs",
      sourcemap: true,
      file: "dist/index.js",
      inlineDynamicImports: true,
      dynamicImportInCjs: false,
    },
    plugins: [
      pathPolyfill(true),
      ...config.plugins,
      copy({
        targets: [
          { src: "src/node-resolve/index.d.ts", dest: "dist/node-resolve" }, // Copy all .d.ts files from src to dist
        ],
      }),
    ],
  },
  {
    ...config,
    input: "src/resolver/index.ts",
    output: {
      format: "esm",
      sourcemap: true,
      file: "dist/resolver.js",
    },
    plugins: [pathPolyfill(), ...config.plugins, nodePolyfills()],
  },
  {
    ...config,
    input: "src/web-fs-loader/index.ts",
    output: {
      format: "esm",
      sourcemap: true,
      file: "dist/browser/web-fs-loader.js",
    },
    plugins: [pathPolyfill(), ...config.plugins, nodePolyfills()],
  },
];
